"use client";

import { RingProgress, RingProgressProps } from '@mantine/core';

function Wrapper(props: RingProgressProps) {
  return (
    <RingProgress
      {...props}
      sections={[
        { value: 40, color: 'cyan' },
        { value: 15, color: 'orange' },
